class Cart {
  #prices = [3, 4];

  get total() {
    return this.#prices[0] + this.#prices[1];
  }
}

const cart = new Cart();
const literal = { get total() { return 7; } };

console.log(JSON.stringify({ ...cart }));
console.log(JSON.stringify({ ...literal }));
console.log("total" in cart);
console.log(Object.getOwnPropertyNames(Cart.prototype).join(","));
